const html = $input.item.json.body || $input.item.json.data || '';

const extractOrigin = (value) => {
  if (!value || typeof value !== 'string') return '';
  try {
    return new URL(value.trim()).origin;
  } catch (error) {
    return '';
  }
};

// Try to find the website URL from previous nodes
let possibleUrl = '';

// 1. Try Extract Data node
if ($node['Extract Data'] && $node['Extract Data'].json) {
  possibleUrl = $node['Extract Data'].json.websiteUrl || $node['Extract Data'].json.url;
}

// 2. Try Form Trigger node
if (!possibleUrl && $node['📋 Form Trigger'] && $node['📋 Form Trigger'].json) {
  possibleUrl = $node['📋 Form Trigger'].json['🌐 URL du Site Web'] || $node['📋 Form Trigger'].json['URL du Site Web'];
}

// 3. Try current input
if (!possibleUrl) {
  possibleUrl = $json.websiteUrl || $json.url || $json['🌐 URL du Site Web'] || $json['URL du Site Web'];
}

let baseUrl = extractOrigin(possibleUrl);

// 4. Fallback to request details in current item
if (!baseUrl) {
  const candidates = [
    $input.item.json.request?.options?.uri?.href,
    $input.item.json.request?.options?.uri,
    $input.item.json.request?.options?.url,
    $input.item.json.request?.uri?.href,
    $input.item.json.request?.uri,
    $input.item.json.request?.url,
    $input.item.json.url
  ];
  for (const candidate of candidates) {
    baseUrl = extractOrigin(candidate);
    if (baseUrl) break;
  }
}

if (!baseUrl) {
  // If no URL found, return empty array to stop execution of this branch
  // but do not throw error
  return [];
}

const urls = [baseUrl];

const allHrefs = html.split('href=');

for (let i = 1; i < allHrefs.length && urls.length < 20; i++) {
  const part = allHrefs[i];
  let url = '';

  if (part[0] === '"') {
    const end = part.indexOf('"', 1);
    if (end > 0) url = part.substring(1, end);
  } else if (part[0] === "'") {
    const end = part.indexOf("'", 1);
    if (end > 0) url = part.substring(1, end);
  }

  if (!url || url[0] === '#' || url.substring(0, 7) === 'mailto:' || url.substring(0, 4) === 'tel:') {
    continue;
  }

  if (url[0] === '/') {
    url = baseUrl + url;
  } else if (url.substring(0, 4) !== 'http') {
    continue;
  }

  if (url.substring(0, baseUrl.length) === baseUrl) {
    const qPos = url.indexOf('?');
    const hPos = url.indexOf('#');
    if (qPos > 0) url = url.substring(0, qPos);
    if (hPos > 0) url = url.substring(0, hPos);

    let found = false;
    for (let j = 0; j < urls.length; j++) {
      if (urls[j] === url) {
        found = true;
        break;
      }
    }
    if (!found) urls.push(url);
  }
}

return urls.map(u => ({ url: u }));

