const items = $input.all();
let combinedHtml = '';
for (const item of items) {
  const url = item.json.pageUrl || '';
  const html = item.json.pageHtml || '';
  combinedHtml += `\n\n---PAGE: ${url}---\n${html}`;
}
return [{ json: { allPagesHtml: combinedHtml } }];
